package com.rpb.reservation.workforce.attendancepolicy;
import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.*;import static com.rpb.reservation.workforce.attendancepolicy.AttendancePolicyDtos.*;
class AttendancePolicyRulesTest {
 @Test void validatesIndependentModesAndArrangements(){assertThat(AttendancePolicyRules.mode("contract")).isEqualTo("contract");assertThatThrownBy(()->AttendancePolicyRules.mode("onsite")).isInstanceOf(RuntimeException.class);var a=new Arrangement(List.of(1,2,3,4,5),LocalTime.of(9,0),480,60,180);assertThat(AttendancePolicyRules.arrangement("default_normal",a)).isEqualTo(a);assertThat(AttendancePolicyRules.arrangement("free",null)).isNull();assertThatThrownBy(()->AttendancePolicyRules.arrangement("clock",null)).isInstanceOf(RuntimeException.class);assertThatThrownBy(()->AttendancePolicyRules.arrangement("clock",new Arrangement(List.of(1,1),LocalTime.NOON,1440,1,180))).isInstanceOf(RuntimeException.class);}
 @Test void breakWindowMustBePrecise(){assertThatThrownBy(()->AttendancePolicyRules.arrangement("default_normal",new Arrangement(List.of(1),LocalTime.NOON,480,60,null))).isInstanceOf(RuntimeException.class);assertThatThrownBy(()->AttendancePolicyRules.arrangement("clock",new Arrangement(List.of(1),LocalTime.NOON,480,60,481))).isInstanceOf(RuntimeException.class);assertThat(AttendancePolicyRules.arrangement("clock",new Arrangement(List.of(1),LocalTime.NOON,480,0,null))).isNotNull();}
 @Test void strictlyFutureAndIncreasing(){AttendancePolicyRules.date(LocalDate.of(2026,11,1),LocalDate.of(2026,10,31),LocalDate.of(2020,1,1),null);assertThatThrownBy(()->AttendancePolicyRules.date(LocalDate.of(2026,10,31),LocalDate.of(2026,10,31),LocalDate.of(2020,1,1),null)).isInstanceOf(RuntimeException.class);}
}
